<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }
$id=(int)($_GET['id']??0);$page=max(1,min((int)($_GET['history_page']??1),100000));$data=appointments_get($id,$page);$lead=$data['lead'];$row=$data['row'];$offered=appointments_public();
$post=is_string($_POST['id']??null) && (int)$_POST['id']===$id?$_POST:[];
$revision=appointments_value($post,'revision',(string)($row['revision']??1));$controls=function(string $action) use ($id,$revision): void {admin_action('appointments_'.$action);echo '<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="revision" value="'.esc($revision).'">';};
?>
<p><a href="<?=esc(admin_url('lead',['id'=>$id]))?>">← Inquiry <?=esc($lead['reference'])?></a></p><h2><?=esc($lead['name'])?></h2><p><?=esc($lead['email'])?> · Contact consent: <?=(int)$lead['consent']===1?'Recorded':'Not recorded'?>.</p>
<p class="notice">Staff decisions update this studio calendar only. Contact the prospect separately; no confirmation, cancellation message or calendar invitation is sent.</p>
<?php if (!$row): ?>
<section class="workspace-card"><h2>Schedule this inquiry</h2><p>Choose an available time after reviewing the original request. Older free-text preferences are not automatically treated as a reserved time.</p>
<?php if ($offered['enabled'] && $offered['slots']): ?><form method="post" data-appointment-adopt><?php $controls('adopt');appointments_slot_select($offered,appointments_value($post,'slot'));appointments_zone_select(appointments_value($post,'timezone',$offered['timezone'])); ?><button class="btn gold">Save pending appointment</button></form><?php else: ?><p>An owner must enable suitable availability before this inquiry can be scheduled.</p><?php endif; ?></section>
<?php else: ?>
<section class="workspace-card"><h2><?=esc($row['status']==='requested'?'Pending confirmation':ucfirst($row['status']))?></h2><p><?=esc(appointments_label((int)$row['starts_at'],(int)$row['ends_at'],$row['timezone']))?></p><p>UTC: <?=esc(gmdate('Y-m-d H:i',(int)$row['starts_at']))?> – <?=esc(gmdate('H:i',(int)$row['ends_at']))?> · Saved version <?=(int)$row['revision']?>. Inquiry sales status remains separate.</p></section>
<?php if ($row['status']==='requested' && (int)$row['starts_at']>time()): ?><form method="post" class="workspace-card" data-appointment-confirm><?php $controls('confirm'); ?><h2>Confirm in the studio calendar</h2><p>Confirm this exact saved time only after checking the prospect's request. This records the staff decision and does not notify the prospect.</p><?php admin_input('current_password','Your current password','','password','required autocomplete="current-password"'); ?><button class="btn gold">Confirm appointment record</button></form><?php endif; ?>
<?php if (in_array($row['status'],['requested','confirmed'],true)): ?>
<?php if ((int)$row['starts_at']>time() && $offered['enabled'] && $offered['slots']): ?><form method="post" class="workspace-card" data-appointment-reschedule><?php $controls('reschedule'); ?><h2>Request a different time</h2><p>Moving an appointment returns it to pending confirmation.</p><?php appointments_slot_select($offered,appointments_value($post,'slot'));appointments_zone_select(appointments_value($post,'timezone',$row['timezone'])); ?><button class="btn outline">Save new pending time</button></form><?php endif; ?>
<section class="workspace-card"><h2>Release this time</h2><p>Declining or cancelling releases this slot and is retained in history. The closed record cannot be reopened.</p><?php if ($row['status']==='requested'): ?><form method="post"><?php $controls('decline'); ?><button class="btn outline">Decline request</button></form><?php endif; ?><form method="post"><?php $controls('cancel'); ?><button class="btn outline">Cancel appointment</button></form></section>
<?php endif; ?>
<h2>Appointment history</h2>
<?php foreach (array_slice($data['history'],0,20) as $item): $saved=json_decode($item['snapshot'],true,16,JSON_THROW_ON_ERROR); ?><details class="workspace-card"><summary>Version <?=(int)$item['revision']?> · <?=esc($item['action'])?> · <?=esc($item['recorded_at'])?> UTC · <?=esc($item['actor_name']??((int)$item['actor_id']===0?'Public request':'Former administrator'))?></summary><p><?=esc(ucfirst($saved['status']))?> · <?=esc(appointments_label((int)$saved['starts_at'],(int)$saved['ends_at'],$saved['timezone']))?></p></details><?php endforeach; ?>
<nav aria-label="Appointment history pages"><?php if ($page>1): ?><a class="btn outline" href="<?=esc(admin_url('consultation',['id'=>$id,'history_page'=>$page-1]))?>">Newer history</a><?php endif; ?><?php if (count($data['history'])>20): ?><a class="btn outline" href="<?=esc(admin_url('consultation',['id'=>$id,'history_page'=>$page+1]))?>">Older history</a><?php endif; ?></nav>
<?php endif; ?>
